/**
 * For #WCCChallenge << Eyes >>
 * Had fun figuring out the equations for the "mobius" shapes
 * And shoutout to Gorillasun (again) for the grainy texture implementation
 **/

let palette = [
  "#0D2732",
  "#B94339",
  "#3559A0",
  "#D2991E",
  "#9E2E52",
  "#C4BEB1",
  "#4C7058",
]
let bgColor = "#153E4F"

class Eye {
  constructor({
    R,
    a,
    x,
    y,
    minWidth,
    maxWidth,
    speed,
		step,
		blinkSpeed = 8,
    color1 = color(0),
    color2 = color(255),
  }) {
    this.resize({ R, a })
    this.color1 = color1
    this.color2 = color2
    this.startAngle = 0
    this.step = step || 5
    this.speed = speed || 0.05
    this.x = x
    this.y = y
    this.minWidth = minWidth || 2
    this.maxWidth = maxWidth || 10
		this.blinkSpeed = blinkSpeed
  }

  draw() {
    push()
    translate(this.x, this.y)
    let r = this.R
    for (let angle = this.startAngle; angle < 360; angle += (Math.max(0.001, Math.abs(this.step)) || 1)) {
      let [a, b, c] = this.getPointsAt(angle)
      let d1 = dist(...a, ...b)
      let d2 = dist(...b, ...c)
      let d3 = d1 + d2
      strokeWeight(map(d2 / d3, 0, 1, this.minWidth, this.maxWidth))
      stroke(lerpColor(this.color2, this.color1, d2 / d3))
      line(...b, ...c)
      stroke(lerpColor(this.color2, this.color1, d1 / d3))
      strokeWeight(map(d1 / d3, 0, 1, this.minWidth, this.maxWidth))
      line(...a, ...b)
    }
    let nd = (this.a - this.pupilSize) / 2
    let ne = nd + this.pupilSize / 6
    let na = atan(((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.y) / ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.x))
    if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.x < 0) {
      na = na + 180
    }
    let pa = nd * cos(na)
    let pb = nd * sin(na)
    let blink = this.pupilSize
    if (this.blinking) {
      blink = map(
        abs(this.blinkingFrame - this.blinkSpeed / 2),
        0,
        this.blinkSpeed / 2,
        0,
        this.pupilSize
      )
    }
    noStroke()
    fill(255)
    ellipse(pa, pb, this.pupilSize, blink)
    fill(0)
    circle(ne * cos(na), ne * sin(na), this.pupilSize / 2)
    pop()
  }

  update() {
    this.startAngle =
      (this.startAngle + (frameCount % this.step) * this.speed) % this.step
    if (this.startAngle < 0) {
      this.startAngle = (this.startAngle + this.step) % this.step
    }
    if (this.blinking) {
      this.blinkingFrame += 1
      if (this.blinkingFrame === this.blinkSpeed) {
        this.blinking = false
      }
    }
  }

  resize({ R, a }) {
    this.R = R
    this.a = a
    this.r = (R + a / 2) / 2
    this.cy1 = -R + this.r
    this.cy2 = R - this.r
    this.pupilSize = this.a * 0.75
  }

	// Returns 3 points:
	// - The first one at the perimeter of the "eye" shape
	// - The second one, corresponding to the transition between the two semicircles
	// - The third one is the outer circle point
  getPointsAt(angle) {
    let R = this.R
    var r = this.r
    let a = this.a
    let nx = R * cos(angle)
    let ny = R * sin(angle)
    let m = tan(angle) // Slope
    // Find the intersections of the radius at angle and the two inner circles
    let intersections = [
      findCircleLineIntersections(r, 0, this.cy1, m, 0),
      findCircleLineIntersections(r, 0, this.cy2, m, 0),
    ]
    let ax, ay // Points on the "eye" shape
    let bx, by // Points going out the inner circles

    if (angle === 90 || angle === 270) {
      ax = 0
    } else {
      let int = angle < 180 ? intersections[0] : intersections[1]
      ax = nx > 0 ? int[0] : int[1]
    }
    if (angle < 180) {
      ay = this.cy1 + sqrt(r ** 2 - ax ** 2)
    } else {
      ay = this.cy2 - sqrt(r ** 2 - ax ** 2)
    }
    if (m <= 0 || angle === 90 || angle === 270) {
      bx = nx
      by = ny
    } else {
      bx = angle < 180 ? intersections[1][0] : intersections[0][1]
      var na, f
      if (angle < 180) {
        na = atan((r - a / 2) / r)
        f = angle < na ? -1 : 1
        by = this.cy2 + f * sqrt(r ** 2 - bx ** 2)
      } else {
        na = atan((r - a / 2) / r) + 180
        f = angle < na ? 1 : -1
        by = this.cy1 + f * sqrt(r ** 2 - bx ** 2)
      }
    }
    return [
      [ax, ay],
      [bx, by],
      [nx, ny],
    ]
  }

  blink() {
    this.blinking = true
    this.blinkingFrame = 0
  }
}

let eyes = []
let cw
function setup() {
  cw = max(windowWidth, windowHeight)
  createCanvas(cw, cw)
  background(bgColor)
  angleMode(DEGREES)
  noFill()
  smooth()
  var R = (cw * 0.9) / 6
  var m = 3 // Small margin between figures
  for (let i = 0; i < 6; i++) {
    eyes.push(
      new Eye({
        R: R - m,
        a: R / 2,
        color2: color(palette[i + 1]),
        color1: color(palette[i]),
        minWidth: 2,
        maxWidth: 5,
        x: cw / 2 + 2 * R * cos(i * 60),
        y: cw / 2 + 2 * R * sin(i * 60),
        speed: i % 2 === 0 ? 0.05 : -0.05,
      })
    )
  }
  eyes.push(
    new Eye({
      R: R - m,
      a: R / 2,
      color1: color(palette[6]),
      color2: color(palette[0]),
      minWidth: 0.2,
      maxWidth: 4,
      x: cw / 2,
      y: cw / 2,
    })
  )
  texture = granulate(100)
}

function draw() {
  background(bgColor)
  for (let i = 0; i < eyes.length; i++) {
		let e = eyes[i]
    e.resize({
      R: e.R,
      a: map(dist(e.x, e.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), sqrt(2*(cw**2)), 0, e.R / 2, (5 * e.R) / 6, true),
    })
    e.update()
    e.draw()
    if (!e.blinking && random() < 0.003) {
      e.blink()
    }
		e.speed = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, cw, 0.1, 0.25) * (i % 2 ? 1 : -1)
  }
  blendMode(DODGE)
  image(texture, 0, 0, cw, cw)
  blendMode(BLEND)
}

let texture
function granulate(gA) {
  let gc = createGraphics(cw, cw)
  gc?.loadPixels?.()
  let d = gc.pixelDensity()
  let halfImage = 4 * (cw * d) * (cw * d)
  for (let ii = 0; ii < halfImage; ii += 4) { // noprotect
    grainAmount = random(-gA, gA)
    gc.pixels[ii] = gc.pixels[ii] + gA
    gc.pixels[ii + 1] = gc.pixels[ii + 1] + grainAmount
    gc.pixels[ii + 2] = gc.pixels[ii + 2] + grainAmount
    gc.pixels[ii + 3] = gc.pixels[ii + 3] + gA
  }
  gc.updatePixels()
  return gc
}

// From https://cscheng.info/2016/06/09/calculate-circle-line-intersection-with-javascript-and-p5js.html
function findCircleLineIntersections(r, h, k, m, n) {
  // circle: (x - h)^2 + (y - k)^2 = r^2
  // line: y = m * x + n
  // r: circle radius
  // h: x value of circle centre
  // k: y value of circle centre
  // m: slope
  // n: y-intercept

  // get a, b, c values
  var a = 1 + sq(m)
  var b = -h * 2 + m * (n - k) * 2
  var c = sq(h) + sq(n - k) - sq(r)

  // get discriminant
  var d = sq(b) - 4 * a * c
  if (d >= 0) {
    // insert into quadratic formula
    var intersections = [
      (-b + sqrt(sq(b) - 4 * a * c)) / (2 * a),
      (-b - sqrt(sq(b) - 4 * a * c)) / (2 * a),
    ]
    if (d == 0) {
      // only 1 intersection
      return [intersections[0]]
    }
    return intersections
  }
  // no intersection
  return []
}
